import React from 'react';
import styled from 'styled-components';

const MainContainer = styled.div`
  text-align: center;
  padding: 40px;
  background-color: #f8f9fa;
  color: #1d3557;
`;

const HeroSection = styled.div`
  background: linear-gradient(135deg, #457b9d, #1d3557);
  color: #f1faee;
  padding: 80px 20px;
  border-radius: 10px;
  box-shadow: 0 8px 12px rgba(0, 0, 0, 0.1);
  margin-bottom: 60px;
`;

const HeroTitle = styled.h1`
  font-size: 3.8rem;
  margin-bottom: 20px;
  font-weight: 700;
`;

const HeroSubtitle = styled.p`
  font-size: 1.5rem;
  margin-bottom: 20px;
`;

const ImagePlaceholder = styled.img`
  width: 100%;
  max-width: 800px;
  border-radius: 10px;
  margin: 40px auto;
  object-fit: cover;
  box-shadow: 0 6px 10px rgba(0, 0, 0, 0.15);
`;

const SectionTitle = styled.h2`
  font-size: 2.8rem;
  margin: 40px 0 20px;
  font-weight: 600;
`;

const ContentParagraph = styled.p`
  font-size: 1.2rem;
  color: #333;
  line-height: 1.8;
  margin: 20px auto;
  max-width: 800px;
  text-align: justify;
`;

const InfoList = styled.ul`
  text-align: left;
  margin: 30px auto;
  max-width: 800px;
  padding: 0;
  list-style: none;
`;

const InfoListItem = styled.li`
  font-size: 1.2rem;
  color: #1d3557;
  margin-bottom: 15px;
  padding-left: 20px;
  position: relative;

  &::before {
    content: "✔";
    color: #457b9d;
    position: absolute;
    left: 0;
    top: 0;
  }
`;

const MainPage = () => {
  return (
    <MainContainer>
      <HeroSection>
        <HeroTitle>Welcome to TriGear</HeroTitle>
        <HeroSubtitle>Your Ultimate Guide for Triathlon and Ironman Competitions</HeroSubtitle>
        <ImagePlaceholder src="https://images.squarespace-cdn.com/content/v1/61b7d0c4c5a10d1c445590cf/1639436551704-BT7W6EV3J6LRPR2VZL21/Drew+Placid+Finish+Hero.jpeg?format=1500w" alt="Triathlon Hero" />
      </HeroSection>

      <SectionTitle>The History of Triathlon and Ironman</SectionTitle>
      <ContentParagraph>
        The sport of triathlon was born in the 1970s in Southern California and has evolved into one of the most challenging endurance events. The concept was simple: combine three sports—swimming, cycling, and running—into one long race. The first official Ironman Triathlon was held in 1978 in Hawaii.
      </ContentParagraph>

      <ImagePlaceholder src="https://kajabi-storefronts-production.kajabi-cdn.com/kajabi-storefronts-production/blogs/34705/images/Vt9lOElaRmum3AkvGvuu_brief_hisotry_blog.png" alt="Triathlon History" />

      <SectionTitle>Beginner Advice: How to Get Started</SectionTitle>
      <InfoList>
        <InfoListItem>Start Small: Choose a sprint triathlon or a shorter distance to begin with.</InfoListItem>
        <InfoListItem>Training Plan: Balance training across swimming, biking, and running.</InfoListItem>
        <InfoListItem>Get the Right Gear: Invest in basic gear like a road bike and running shoes.</InfoListItem>
        <InfoListItem>Practice Transitions: Learn to transition efficiently between activities.</InfoListItem>
        <InfoListItem>Join a Community: Connect with local or online triathlete groups.</InfoListItem>
      </InfoList>
    </MainContainer>
  );
};

export default MainPage;
